part of 'login_response.dart';

LoginResponse _$LoginResponseFromJson(Map<String, dynamic> json) =>
    LoginResponse(
      userId: json['user_id'] as String,
      name: json['name'] as String,
      roleId: json['role_id'] as String,
      pokjar: json['pokjar'] as String,
      nrp: json['nrp'] as String,
      nosis: json['nosis'] as String? ?? '-',
      pangkat: json['pangkat'] as String,
      angkatan: json['angkatan'] as String,
      agama: json['agama'] as String,
      jenisKelamin: json['jenis_kelamin'] as String? ?? '-',
      jabatan: json['jabatan'] as String,
      noSerdik: json['no_serdik'] as String? ?? '-',
      nik: json['nik'] as String? ?? '-',
      jabatanSenat: json['jabatan_senat'] as String? ?? '-',
      tempatLahir: json['tempat_lahir'] as String? ?? '-',
      noHandphone: json['no_handphone'] as String? ?? '-',
      pendidikanTerakhir: json['pendidikan_terakhir'] as String? ?? '-',
      alamatLengkap: json['alamat_lengkap'] as String? ?? '-',
      email: json['email'] as String? ?? '-',
      noTelepon: json['no_telepon'] as String? ?? '-',
      kelompok: json['kelompok'] as String? ?? '-',
      diktukAwal: json['diktuk_awal'] as String? ?? '-',
      tahunDiktuk: json['tahun_diktuk'] as String? ?? '-',
      personel: json['personel'] as String? ?? '-',
      satker: json['satker'] as String? ?? '-',
      tanggalLahir: json['tanggal_lahir'] as String? ?? '1990-01-01',
      eselon: json['eselon'] as String? ?? '-',
      golongan: json['golongan'] as String? ?? '-',
      isNakApproved: json['is_nak_approved'] as bool? ?? false,
      nilaiAkademik: (json['nilai_akademik'] as num?)?.toDouble() ?? 0.0,
      nilaiMental: (json['nilai_mental'] as num?)?.toDouble() ?? 0.0,
      nilaiJasmani: (json['nilai_jasmani'] as num?)?.toDouble() ?? 0.0,
      accessToken: json['access_token'] as String,
      refreshToken: json['refresh_token'] as String,
    );

Map<String, dynamic> _$LoginResponseToJson(LoginResponse instance) =>
    <String, dynamic>{
      'user_id': instance.userId,
      'name': instance.name,
      'role_id': instance.roleId,
      'pokjar': instance.pokjar,
      'nrp': instance.nrp,
      'nosis': instance.nosis,
      'pangkat': instance.pangkat,
      'angkatan': instance.angkatan,
      'agama': instance.agama,
      'jabatan': instance.jabatan,
      'no_serdik': instance.noSerdik,
      'nik': instance.nik,
      'jabatan_senat': instance.jabatanSenat,
      'tempat_lahir': instance.tempatLahir,
      'no_handphone': instance.noHandphone,
      'pendidikan_terakhir': instance.pendidikanTerakhir,
      'alamat_lengkap': instance.alamatLengkap,
      'email': instance.email,
      'no_telepon': instance.noTelepon,
      'kelompok': instance.kelompok,
      'diktuk_awal': instance.diktukAwal,
      'tahun_diktuk': instance.tahunDiktuk,
      'personel': instance.personel,
      'satker': instance.satker,
      'tanggal_lahir': instance.tanggalLahir,
      'eselon': instance.eselon,
      'golongan': instance.golongan,
      'is_nak_approved': instance.isNakApproved,
      'jenis_kelamin': instance.jenisKelamin,
      'nilai_akademik': instance.nilaiAkademik,
      'nilai_mental': instance.nilaiMental,
      'nilai_jasmani': instance.nilaiJasmani,
      'access_token': instance.accessToken,
      'refresh_token': instance.refreshToken,
    };
